import React, { useState } from 'react';
import { 
  Palette, Monitor, Smartphone, Tablet,
  Sun, Moon, Contrast, Eye, EyeOff,
  Grid, List, Layout, Check,
  Type, Maximize2, Minus
} from 'lucide-react';

const DisplaySettings = () => {
  const [theme, setTheme] = useState('dark');
  const [density, setDensity] = useState('comfortable');
  const [fontSize, setFontSize] = useState('medium');
  const [contrast, setContrast] = useState('normal');
  const [animations, setAnimations] = useState(true);

  const themes = [
    { 
      id: 'light', 
      label: 'Clair', 
      icon: <Sun className="h-5 w-5" />, 
      color: 'from-white to-neutral-100',
      border: 'border-neutral-300'
    },
    { 
      id: 'dark', 
      label: 'Sombre', 
      icon: <Moon className="h-5 w-5" />, 
      color: 'from-neutral-900 to-neutral-800',
      border: 'border-neutral-700'
    },
    { 
      id: 'auto', 
      label: 'Auto', 
      icon: <Contrast className="h-5 w-5" />, 
      color: 'from-white via-neutral-400 to-neutral-900',
      border: 'border-neutral-400'
    }
  ];

  const densities = [
    { 
      id: 'compact', 
      label: 'Compact', 
      description: 'Plus d\'éléments par page',
      icon: <Grid className="h-4 w-4" />
    },
    { 
      id: 'comfortable', 
      label: 'Confortable', 
      description: 'Espacement équilibré',
      icon: <Layout className="h-4 w-4" />
    },
    { 
      id: 'spacious', 
      label: 'Spacieux', 
      description: 'Plus d\'espace entre les éléments',
      icon: <List className="h-4 w-4" />
    }
  ];

  const fontSizes = [
    { id: 'small', label: 'Petit', size: 'text-sm', preview: 'Aa' },
    { id: 'medium', label: 'Moyen', size: 'text-base', preview: 'Aa' },
    { id: 'large', label: 'Grand', size: 'text-lg', preview: 'Aa' },
    { id: 'xlarge', label: 'Très grand', size: 'text-xl', preview: 'Aa' }
  ];

  const accessibilityOptions = [
    {
      id: 'reducedMotion',
      label: 'Réduire les animations',
      description: 'Désactive les animations inutiles',
      enabled: !animations
    },
    {
      id: 'highContrast',
      label: 'Mode haut contraste',
      description: 'Améliore la lisibilité',
      enabled: contrast === 'high'
    },
    {
      id: 'focusIndicators',
      label: 'Indicateurs de focus',
      description: 'Affiche les indicateurs de focus',
      enabled: true
    }
  ];

  const toggleAccessibility = (id) => {
    if (id === 'reducedMotion') {
      setAnimations(!animations);
    } else if (id === 'highContrast') {
      setContrast(contrast === 'high' ? 'normal' : 'high');
    }
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="bg-gradient-to-br from-white to-white/80 dark:from-neutral-900 dark:to-neutral-900/80 backdrop-blur-xl rounded-3xl shadow-xl border border-white/40 dark:border-neutral-800/60 p-6">
        <div className="flex items-center space-x-3 mb-6">
          <div className="h-12 w-12 rounded-2xl bg-gradient-to-r from-purple-500 to-pink-400 flex items-center justify-center">
            <Palette className="h-6 w-6 text-white" />
          </div>
          <div>
            <h3 className="text-lg font-bold text-neutral-900 dark:text-white">Affichage et accessibilité</h3>
            <p className="text-sm text-neutral-600 dark:text-neutral-400">Personnalisez l'apparence de l'interface</p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Theme Settings */}
        <div className="bg-gradient-to-br from-white to-white/80 dark:from-neutral-900 dark:to-neutral-900/80 backdrop-blur-xl rounded-3xl shadow-xl border border-white/40 dark:border-neutral-800/60 p-6">
          <h4 className="font-semibold text-neutral-900 dark:text-white mb-6 flex items-center">
            <Sun className="h-5 w-5 mr-2 text-amber-500" />
            Thème et couleur
          </h4>

          {/* Theme Selection */}
          <div className="mb-8">
            <div className="grid grid-cols-3 gap-4">
              {themes.map((themeOption) => (
                <button
                  key={themeOption.id}
                  onClick={() => setTheme(themeOption.id)}
                  className={`relative p-4 rounded-2xl border-2 transition-all duration-300 group ${
                    theme === themeOption.id
                      ? 'border-primary-500 ring-2 ring-primary-500/20 bg-gradient-to-br from-primary-50 to-primary-100/30 dark:from-primary-900/20 dark:to-primary-800/10'
                      : `border-transparent hover:border-neutral-300 dark:hover:border-neutral-700 hover:bg-neutral-50 dark:hover:bg-neutral-800/30`
                  }`}
                >
                  <div className={`h-16 rounded-xl bg-gradient-to-r ${themeOption.color} border ${themeOption.border} flex items-center justify-center mb-3 transition-transform group-hover:scale-105`}>
                    {themeOption.icon}
                  </div>
                  <p className="font-medium text-neutral-900 dark:text-white text-center">{themeOption.label}</p>
                  {theme === themeOption.id && (
                    <div className="absolute -top-2 -right-2 h-6 w-6 rounded-full bg-primary-500 flex items-center justify-center">
                      <Check className="h-3 w-3 text-white" />
                    </div>
                  )}
                </button>
              ))}
            </div>
          </div>

          {/* Color Palette Preview */}
          <div className="mb-6">
            <h5 className="text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-3">Palette de couleurs</h5>
            <div className="grid grid-cols-5 gap-2">
              {['from-primary-500 to-secondary-500', 'from-blue-500 to-cyan-400', 'from-purple-500 to-pink-400', 'from-emerald-500 to-teal-400', 'from-amber-500 to-orange-400'].map((gradient, index) => (
                <div
                  key={index}
                  className={`h-8 rounded-lg bg-gradient-to-r ${gradient} cursor-pointer hover:scale-110 transition-transform duration-300`}
                />
              ))}
            </div>
          </div>
        </div>

        {/* Display Density */}
        <div className="bg-gradient-to-br from-white to-white/80 dark:from-neutral-900 dark:to-neutral-900/80 backdrop-blur-xl rounded-3xl shadow-xl border border-white/40 dark:border-neutral-800/60 p-6">
          <h4 className="font-semibold text-neutral-900 dark:text-white mb-6 flex items-center">
            <Layout className="h-5 w-5 mr-2 text-blue-500" />
            Densité d'affichage
          </h4>

          <div className="space-y-4 mb-8">
            {densities.map((densityOption) => (
              <button
                key={densityOption.id}
                onClick={() => setDensity(densityOption.id)}
                className={`w-full p-4 rounded-2xl transition-all duration-300 text-left group ${
                  density === densityOption.id
                    ? 'bg-gradient-to-r from-primary-500/10 to-secondary-500/10 border border-primary-500/30'
                    : 'hover:bg-neutral-50 dark:hover:bg-neutral-800/30'
                }`}
              >
                <div className="flex items-center justify-between">
                  <div className="flex items-center space-x-3">
                    <div className={`h-10 w-10 rounded-lg flex items-center justify-center ${
                      density === densityOption.id
                        ? 'bg-primary-500/10 text-primary-500'
                        : 'bg-neutral-100 dark:bg-neutral-800 text-neutral-400'
                    }`}>
                      {densityOption.icon}
                    </div>
                    <div>
                      <p className="font-medium text-neutral-900 dark:text-white">{densityOption.label}</p>
                      <p className="text-sm text-neutral-600 dark:text-neutral-400">{densityOption.description}</p>
                    </div>
                  </div>
                  {density === densityOption.id && (
                    <div className="h-5 w-5 rounded-full bg-primary-500 flex items-center justify-center">
                      <Check className="h-3 w-3 text-white" />
                    </div>
                  )}
                </div>
              </button>
            ))}
          </div>

          {/* Density Preview */}
          <div className="mb-6">
            <h5 className="text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-3">Aperçu</h5>
            <div className="p-4 rounded-xl bg-neutral-50 dark:bg-neutral-800/50">
              <div className="flex space-x-2 mb-2">
                {density === 'compact' ? (
                  <>
                    {[...Array(8)].map((_, i) => (
                      <div key={i} className="h-3 flex-1 rounded bg-gradient-to-r from-primary-500 to-secondary-500"></div>
                    ))}
                  </>
                ) : density === 'comfortable' ? (
                  <>
                    {[...Array(6)].map((_, i) => (
                      <div key={i} className="h-4 flex-1 rounded bg-gradient-to-r from-primary-500 to-secondary-500"></div>
                    ))}
                  </>
                ) : (
                  <>
                    {[...Array(4)].map((_, i) => (
                      <div key={i} className="h-6 flex-1 rounded bg-gradient-to-r from-primary-500 to-secondary-500"></div>
                    ))}
                  </>
                )}
              </div>
            </div>
          </div>
        </div>

        {/* Font Size */}
        <div className="bg-gradient-to-br from-white to-white/80 dark:from-neutral-900 dark:to-neutral-900/80 backdrop-blur-xl rounded-3xl shadow-xl border border-white/40 dark:border-neutral-800/60 p-6">
          <h4 className="font-semibold text-neutral-900 dark:text-white mb-6 flex items-center">
            <Type className="h-5 w-5 mr-2 text-emerald-500" />
            Typographie
          </h4>

          <div className="space-y-4 mb-6">
            {fontSizes.map((size) => (
              <button
                key={size.id}
                onClick={() => setFontSize(size.id)}
                className={`w-full p-4 rounded-2xl transition-all duration-300 text-left group ${
                  fontSize === size.id
                    ? 'bg-gradient-to-r from-emerald-500/10 to-teal-400/10 border border-emerald-500/30'
                    : 'hover:bg-neutral-50 dark:hover:bg-neutral-800/30'
                }`}
              >
                <div className="flex items-center justify-between">
                  <div className="flex items-center space-x-4">
                    <span className={`${size.size} font-bold ${
                      fontSize === size.id 
                        ? 'text-emerald-600 dark:text-emerald-400' 
                        : 'text-neutral-900 dark:text-white'
                    }`}>
                      {size.preview}
                    </span>
                    <div>
                      <p className={`font-medium ${fontSize === size.id ? 'text-emerald-600 dark:text-emerald-400' : 'text-neutral-900 dark:text-white'}`}>
                        {size.label}
                      </p>
                      <p className="text-sm text-neutral-600 dark:text-neutral-400">Taille de texte</p>
                    </div>
                  </div>
                  {fontSize === size.id && (
                    <div className="h-5 w-5 rounded-full bg-emerald-500 flex items-center justify-center">
                      <Check className="h-3 w-3 text-white" />
                    </div>
                  )}
                </div>
              </button>
            ))}
          </div>

          {/* Font Family */}
          <div>
            <h5 className="text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-3">Famille de police</h5>
            <div className="grid grid-cols-2 gap-3">
              {[
                { name: 'Inter', value: 'Inter, sans-serif', current: true },
                { name: 'Roboto', value: 'Roboto, sans-serif' },
                { name: 'SF Pro', value: '-apple-system, system-ui' },
                { name: 'Segoe UI', value: 'Segoe UI, system-ui' }
              ].map((font) => (
                <div
                  key={font.name}
                  className={`p-3 rounded-xl border cursor-pointer transition-all duration-300 ${
                    font.current
                      ? 'border-primary-500 bg-primary-500/5'
                      : 'border-neutral-200 dark:border-neutral-700 hover:border-primary-500/50'
                  }`}
                  style={{ fontFamily: font.value }}
                >
                  <p className="font-medium text-neutral-900 dark:text-white">{font.name}</p>
                  <p className="text-xs text-neutral-500 dark:text-neutral-500 mt-1">Aa Bb Cc</p>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Accessibility */}
        <div className="bg-gradient-to-br from-white to-white/80 dark:from-neutral-900 dark:to-neutral-900/80 backdrop-blur-xl rounded-3xl shadow-xl border border-white/40 dark:border-neutral-800/60 p-6">
          <h4 className="font-semibold text-neutral-900 dark:text-white mb-6 flex items-center">
            <Eye className="h-5 w-5 mr-2 text-secondary-500" />
            Accessibilité
          </h4>

          <div className="space-y-4 mb-8">
            {accessibilityOptions.map((option) => (
              <div 
                key={option.id}
                className="flex items-center justify-between p-4 rounded-2xl bg-neutral-50 dark:bg-neutral-800/30 hover:bg-neutral-100 dark:hover:bg-neutral-800/50 transition-colors"
              >
                <div className="flex-1">
                  <p className="font-medium text-neutral-900 dark:text-white">{option.label}</p>
                  <p className="text-sm text-neutral-600 dark:text-neutral-400">{option.description}</p>
                </div>
                <button
                  onClick={() => toggleAccessibility(option.id)}
                  className={`relative inline-flex h-6 w-11 items-center rounded-full transition-all duration-300 ${
                    option.enabled
                      ? 'bg-secondary-500 hover:bg-secondary-600'
                      : 'bg-neutral-300 dark:bg-neutral-700 hover:bg-neutral-400 dark:hover:bg-neutral-600'
                  }`}
                >
                  <span className={`inline-block h-4 w-4 transform rounded-full bg-white transition ${
                    option.enabled ? 'translate-x-6' : 'translate-x-1'
                  }`} />
                </button>
              </div>
            ))}
          </div>

          {/* Contrast Settings */}
          <div className="mb-6">
            <h5 className="text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-3">Contraste</h5>
            <div className="grid grid-cols-3 gap-3">
              <button
                onClick={() => setContrast('normal')}
                className={`p-3 rounded-xl border text-center transition-all duration-300 ${
                  contrast === 'normal'
                    ? 'border-primary-500 bg-primary-500/5'
                    : 'border-neutral-200 dark:border-neutral-700 hover:border-primary-500/50'
                }`}
              >
                <div className="h-8 rounded-lg bg-gradient-to-r from-neutral-200 to-neutral-300 dark:from-neutral-700 dark:to-neutral-600 mb-2"></div>
                <p className="text-xs font-medium text-neutral-900 dark:text-white">Normal</p>
              </button>
              <button
                onClick={() => setContrast('high')}
                className={`p-3 rounded-xl border text-center transition-all duration-300 ${
                  contrast === 'high'
                    ? 'border-primary-500 bg-primary-500/5'
                    : 'border-neutral-200 dark:border-neutral-700 hover:border-primary-500/50'
                }`}
              >
                <div className="h-8 rounded-lg bg-gradient-to-r from-black to-neutral-800 dark:from-white dark:to-neutral-200 mb-2"></div>
                <p className="text-xs font-medium text-neutral-900 dark:text-white">Élevé</p>
              </button>
              <button
                onClick={() => setContrast('inverted')}
                className={`p-3 rounded-xl border text-center transition-all duration-300 ${
                  contrast === 'inverted'
                    ? 'border-primary-500 bg-primary-500/5'
                    : 'border-neutral-200 dark:border-neutral-700 hover:border-primary-500/50'
                }`}
              >
                <div className="h-8 rounded-lg bg-gradient-to-r from-white to-neutral-100 dark:from-neutral-900 dark:to-neutral-800 border border-neutral-300 dark:border-neutral-700 mb-2"></div>
                <p className="text-xs font-medium text-neutral-900 dark:text-white">Inversé</p>
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Preview Section */}
      <div className="bg-gradient-to-br from-white to-white/80 dark:from-neutral-900 dark:to-neutral-900/80 backdrop-blur-xl rounded-3xl shadow-xl border border-white/40 dark:border-neutral-800/60 p-6">
        <h4 className="font-semibold text-neutral-900 dark:text-white mb-6 flex items-center">
          <Monitor className="h-5 w-5 mr-2 text-amber-500" />
          Aperçu en direct
        </h4>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {/* Desktop Preview */}
          <div className="relative">
            <div className="absolute -top-2 left-1/2 -translate-x-1/2 bg-neutral-900 dark:bg-neutral-800 text-white text-xs px-3 py-1 rounded-full">
              Desktop
            </div>
            <div className="pt-6 border-2 border-neutral-200 dark:border-neutral-700 rounded-xl p-4 bg-gradient-to-br from-neutral-50 to-white dark:from-neutral-900 dark:to-neutral-800">
              <div className="flex space-x-2 mb-4">
                <div className="h-2 w-2 rounded-full bg-red-500"></div>
                <div className="h-2 w-2 rounded-full bg-amber-500"></div>
                <div className="h-2 w-2 rounded-full bg-emerald-500"></div>
              </div>
              <div className="space-y-2">
                <div className="h-3 rounded bg-gradient-to-r from-primary-500 to-secondary-500"></div>
                <div className="h-3 rounded bg-gradient-to-r from-primary-400 to-secondary-400"></div>
                <div className="h-3 rounded bg-gradient-to-r from-primary-300 to-secondary-300"></div>
              </div>
            </div>
          </div>

          {/* Tablet Preview */}
          <div className="relative">
            <div className="absolute -top-2 left-1/2 -translate-x-1/2 bg-neutral-900 dark:bg-neutral-800 text-white text-xs px-3 py-1 rounded-full">
              Tablet
            </div>
            <div className="pt-6 border-2 border-neutral-200 dark:border-neutral-700 rounded-xl p-4 bg-gradient-to-br from-neutral-50 to-white dark:from-neutral-900 dark:to-neutral-800 max-w-xs mx-auto">
              <div className="h-1 w-8 bg-neutral-300 dark:bg-neutral-700 rounded-full mx-auto mb-4"></div>
              <div className="space-y-2">
                <div className="h-3 rounded bg-gradient-to-r from-primary-500 to-secondary-500"></div>
                <div className="h-3 rounded bg-gradient-to-r from-primary-400 to-secondary-400"></div>
              </div>
            </div>
          </div>

          {/* Mobile Preview */}
          <div className="relative">
            <div className="absolute -top-2 left-1/2 -translate-x-1/2 bg-neutral-900 dark:bg-neutral-800 text-white text-xs px-3 py-1 rounded-full">
              Mobile
            </div>
            <div className="pt-6 border-2 border-neutral-200 dark:border-neutral-700 rounded-2xl p-4 bg-gradient-to-br from-neutral-50 to-white dark:from-neutral-900 dark:to-neutral-800 max-w-[200px] mx-auto">
              <div className="h-1 w-12 bg-neutral-300 dark:bg-neutral-700 rounded-full mx-auto mb-4"></div>
              <div className="space-y-2">
                <div className="h-3 rounded bg-gradient-to-r from-primary-500 to-secondary-500"></div>
              </div>
            </div>
          </div>
        </div>

        <div className="mt-6 pt-6 border-t border-neutral-200 dark:border-neutral-800">
          <div className="flex items-center justify-between">
            <div>
              <p className="font-medium text-neutral-900 dark:text-white">Appliquer les changements</p>
              <p className="text-sm text-neutral-600 dark:text-neutral-400">Les modifications prendront effet immédiatement</p>
            </div>
            <button className="px-6 py-3 rounded-xl bg-gradient-to-r from-primary-500 to-secondary-500 text-white hover:shadow-lg hover:shadow-primary-500/25 transition-all duration-300">
              Appliquer maintenant
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default DisplaySettings;
